import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.doxMM-x8.js";const u=JSON.parse('{"title":"Read the overview and filter devices","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/operations-overview","contentType":"tutorial","prev":{"text":"Lab Records and Current-page CSV","link":"/en/tutorials/lab-records"},"next":false},"headers":[],"relativePath":"en/tutorials/operations-overview.md","filePath":"en/tutorials/operations-overview.md"}'),n={name:"en/tutorials/operations-overview.md"};function s(o,e,d,l,c,p){return a(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="read-the-overview-and-filter-devices" tabindex="-1">Read the overview and filter devices <a class="header-anchor" href="#read-the-overview-and-filter-devices" aria-label="Permalink to &quot;Read the overview and filter devices&quot;">​</a></h1><p>Goal: scan devices, Tasks, key observations, and attention facts in one Lab. Then open the original device. These views share the World subscription and Entity detail.</p><h2 id="starting-state" tabindex="-1">Starting state <a class="header-anchor" href="#starting-state" aria-label="Permalink to &quot;Starting state&quot;">​</a></h2><p>Complete <a href="./device-details">device operations</a>, <a href="./device-trends">device trends</a>, or <a href="./lab-records">Lab records</a>. Register at least one light and one temperature sensor. Use a valid Member session. An Agent needs a valid <code>lab:full</code> API key. The server uses Node 24. Linux and Windows do not need Docker.</p><p>From the repository root, run <code>pnpm install --frozen-lockfile</code>, then <code>pnpm dev</code>. Viewing does not change devices, layouts, or registered locations. Device operations still write persistent records.</p><p>Source: <a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/packages/views/src/lab/workbench-context.tsx" target="_blank" rel="noreferrer">workbench</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/packages/views/src/lab/operations-view.tsx" target="_blank" rel="noreferrer">operations view</a>, <a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/packages/views/src/lab/operations-state.ts" target="_blank" rel="noreferrer">summaries and regions</a>, and <a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/packages/views/src/lab/observation-state.ts" target="_blank" rel="noreferrer">property validity</a>. Lab owns these business rules. Platform Core owns identity and sessions.</p><h2 id="open-the-original-device" tabindex="-1">Open the original device <a class="header-anchor" href="#open-the-original-device" aria-label="Permalink to &quot;Open the original device&quot;">​</a></h2><ol><li>Open <code>http://127.0.0.1:5173/lab</code> and sign in. Without a <code>view</code> parameter, Lab first opens “3D space”.</li><li>Select “Overview”. Read Registered devices, Active Tasks, Current valid observations, and Devices needing attention.</li><li>Select “Registered devices”. The directory includes active instrument, iot, sensor, and robot Entities. Unplaced devices count. Multiple Scene Nodes count once per Entity.</li><li>Select a device name. The shared “Object information” shows the same Entity&#39;s values, source, Run, Task, and result. Closing detail returns focus to its entry.</li><li>Return to “Overview”. Select an “Environment sensor” registered in this Lab. Choose 1, 6, or 24 hours. Read real samples and gaps.</li><li>In “Recent activity”, select “Open original Entity”. Detail shows the result stored in that record. A new Task or Run cannot replace it.</li><li>Select “View all Lab records”. Continue with device, category, and time filters.</li></ol><p>Recent activity reads at most five records from the first page. It excludes raw Observations and does not represent complete history. Environment trends reuse <a href="./device-trends">device trend</a> queries, sampling, and source descriptions. Without a registered sensor, the view shows an empty state.</p><h2 id="interpret-the-summaries" tabindex="-1">Interpret the summaries <a class="header-anchor" href="#interpret-the-summaries" aria-label="Permalink to &quot;Interpret the summaries&quot;">​</a></h2><p>Active Task stages are pending, preparing, running, and decelerating. A running program Run does not prove an active Task exists.</p><p>All required key properties must match the fixed definition, current Binding, and running Run. Their source times must be known. Quality must be good and freshness current. Only then does the device count as having current valid observations. <code>0</code> and <code>false</code> are valid. Unknown values stay unknown. A heartbeat or another property&#39;s update cannot refresh an old property.</p><p>“Needs attention” merges retained interruption, failure, uncertain result, expiration, quality, and unknown source time facts for each device. Uncertain results and interruptions come first. Within a priority, the earliest relevant fact comes first. Normal stops, programs not started, and absent Bindings remain separate. A live connection does not prove device health. This page has no alert acknowledgment, notification, or work order process.</p><h2 id="filter-regions-and-retain-space-access" tabindex="-1">Filter regions and retain space access <a class="header-anchor" href="#filter-regions-and-retain-space-access" aria-label="Permalink to &quot;Filter regions and retain space access&quot;">​</a></h2><ol><li>Open “Devices”. In “Search name or identity”, enter a name, identity fragment, or existing label.</li><li>Select “Runtime status”. Summary buttons also open their matching set.</li><li>Select “Registered region” or “No registered region”. Manual <code>located_in</code> and <code>contains</code> relationships identify the nearest Location. Placement cannot establish a region.</li><li>Select “Unplaced objects only”. A device without Scene Nodes remains accessible.</li><li>Select “Full object directory”. The space directory still provides furniture, labware, locations, and models.</li><li>Select “Archived objects”. Archived identities and retained records remain accessible.</li></ol><p>View changes preserve valid filters, the selected Entity, and unsaved layout drafts. Open <code>/lab?lab=&lt;lab-uuid&gt;&amp;view=devices&amp;entity=&lt;entity-uuid&gt;</code>, then refresh. The same device opens. Replace the Entity with a missing identity. The view shows “Entity not found”. Select “Clear Entity link” to continue in the current view. A missing Lab cannot silently select another Lab.</p><h2 id="recover-after-disconnecting" tabindex="-1">Recover after disconnecting <a class="header-anchor" href="#recover-after-disconnecting" aria-label="Permalink to &quot;Recover after disconnecting&quot;">​</a></h2><ol><li>Keep the page open. Disconnect the network with browser developer tools.</li><li>Read “Last synchronized snapshot · Read only” and its time. Loaded content and inputs remain. New writes are disabled. Last reported values do not prove current measurements.</li><li>Restore the network or select “Reconnect”. The workbench refreshes World, visible environment trends, and recent activity. Valid filters and layout drafts remain.</li><li>If the session expires or is revoked, sign in again. The new identity cannot use old subscriptions or operation attempts.</li></ol><p>Failed trend or activity queries retain previously loaded content and show the failure. Use the reader&#39;s refresh or retry button. Old curves, accepted Commands, and snapshots cannot prove a device action completed.</p><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p>Run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/lab-operations.test.tsx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/e2e/lab-operations.spec.ts</span></span></code></pre></div><p>Views checks use MSW only for HTTP. Browser checks use an isolated Node service and temporary persistent directory. They preserve existing development data. They check a Member, second browser, and Agent against the same World, at desktop and existing agreed narrow viewports. CI retains World, realtime, and bundle budgets.</p><hr><p>Source version：<code>847a4609ed29</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/847a4609ed29871c5721b4e03dc3edd3953b8f28/docs/tutorials/operations-overview.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,25)])])}const v=t(n,[["render",s]]);export{u as __pageData,v as default};
